function activatePower(p){const types=[{type:'fire',label:'FIRE SHOT',time:7},{type:'speed',label:'SPEED BOOST',time:7},{type:'freeze',label:'FREEZE RIVAL',time:4}];const e=types[Math.floor(Math.random()*types.length)];powerEffect={...e,time:e.time,team:0};if(e.type==='speed')p.boost=7;if(e.type==='freeze')players.filter(q=>q.team===1).forEach(q=>q.freeze=4);particleBurst(powerOrb.x,powerOrb.y,purple,34,1);powerOrb=null;updateHUD();}
function aiMove(p,dt){if(p.freeze>0)return {x:0,y:0};const allies=players.filter(q=>q.team===p.team),opponents=players.filter(q=>q.team!==p.team);let tx=ball.x,ty=ball.y;const nearest=allies.slice().sort((a,b)=>hypot(a.x-ball.x,a.y-ball.y)-hypot(b.x-ball.x,b.y-ball.y))[0];if(p.team===0){if(p===nearest){tx=ball.x+ball.vx*.12;ty=ball.y+ball.vy*.12;}else{tx=clamp(ball.x-field.w*.25,field.x+22,field.x+field.w-22);ty=clamp(ball.y+field.h*.22,field.y+field.h*.48,field.y+field.h*.82);}}else{if(p===nearest){tx=ball.x+ball.vx*.16;ty=ball.y+ball.vy*.16;}else{tx=clamp(ball.x+field.w*.22,field.x+22,field.x+field.w-22);ty=clamp(ball.y-field.h*.2,field.y+field.h*.18,field.y+field.h*.53);}}
// Aim to approach behind the ball relative to the opponent goal.
if(p===nearest){const goalY=p.team===0?field.y-25:field.y+field.h+25;let ax=ball.x,ay=ball.y;const dx=ball.x-W/2,dy=ball.y-goalY,l=hypot(dx,dy)||1;tx=ax+dx/l*(p.r+ball.r+7);ty=ay+dy/l*(p.r+ball.r+7);}
const dx=tx-p.x,dy=ty-p.y,d=hypot(dx,dy)||1;if(d>p.r*.8&&d>75&&p.dashCd<=0&&Math.random()<dt*.55)dash(p);return{x:dx/d,y:dy/d};}
function movePlayer(p,ax,ay,dt){if(p.freeze>0){p.freeze=Math.max(0,p.freeze-dt);ax=ay=0;}const boost=p.boost>0?1.32:1,speed=(p.human?210:184)*boost;const l=hypot(ax,ay);if(l>1){ax/=l;ay/=l;}if(l>.1){p.faceX=ax;p.faceY=ay;}const accel= p.dash>0?0:1000; p.vx+=ax*accel*dt;p.vy+=ay*accel*dt;const max=speed+(p.dash>0?310:0),v=hypot(p.vx,p.vy);if(v>max){p.vx*=max/v;p.vy*=max/v;}const drag=Math.pow(p.dash>0?.992:.84,dt*60);p.vx*=drag;p.vy*=drag;p.x+=p.vx*dt;p.y+=p.vy*dt;p.dash=Math.max(0,p.dash-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.kickFlash=Math.max(0,p.kickFlash-dt);p.boost=Math.max(0,p.boost-dt);p.x=clamp(p.x,field.x+p.r,field.x+field.w-p.r);p.y=clamp(p.y+0,field.y+p.r,field.y+field.h-p.r);}
function collidePlayers(){for(let i=0;i<players.length;i++)for(let j=i+1;j<players.length;j++){const a=players[i],b=players[j],dx=b.x-a.x,dy=b.y-a.y,d=hypot(dx,dy),min=a.r+b.r;if(d&&d<min){const nx=dx/d,ny=dy/d,over=min-d;a.x-=nx*over*.5;a.y-=ny*over*.5;b.x+=nx*over*.5;b.y+=ny*over*.5;const rel=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(rel<0){const impulse=-rel*.72;a.vx-=impulse*nx;a.vy-=impulse*ny;b.vx+=impulse*nx;b.vy+=impulse*ny;}if(a.dash>0&&a.team!==b.team){b.vx+=nx*90;b.vy+=ny*90;}}}}
function collideBall(){for(const p of players){const dx=ball.x-p.x,dy=ball.y-p.y,d=hypot(dx,dy),min=p.r+ball.r;if(d<min&&d>0){const nx=dx/d,ny=dy/d,over=min-d;ball.x+=nx*over;ball.y+=ny*over;const rel=(ball.vx-p.vx)*nx+(ball.vy-p.vy)*ny;if(rel<0){const impulse=-(1.62)*rel;ball.vx+=impulse*nx+p.vx*.08;ball.vy+=impulse*ny+p.vy*.08;}}}}
function updateBall(dt){ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;const friction=Math.pow(.986,dt*60);ball.vx*=friction;ball.vy*=friction;const l=hypot(ball.vx,ball.vy);if(l<4)ball.vx=ball.vy=0;if(l>760){ball.vx*=760/l;ball.vy*=760/l;}ball.trail.unshift({x:ball.x,y:ball.y});if(ball.trail.length>12)ball.trail.pop();const left=field.x+ball.r,right=field.x+field.w-ball.r,top=field.y+ball.r,bottom=field.y+field.h-ball.r,goalLeft=W/2-field.goalW/2,goalRight=W/2+field.goalW/2;
if(ball.x<left){ball.x=left;ball.vx=Math.abs(ball.vx)*.82;particleBurst(ball.x,ball.y,'#6eb6c5',3,.25);}if(ball.x>right){ball.x=right;ball.vx=-Math.abs(ball.vx)*.82;particleBurst(ball.x,ball.y,'#6eb6c5',3,.25);}
if(ball.y<top){if(ball.x>goalLeft&&ball.x<goalRight){if(ball.y<field.y-field.goalDepth){goal(0);return;}}else{ball.y=top;ball.vy=Math.abs(ball.vy)*.82;}}
if(ball.y>bottom){if(ball.x>goalLeft&&ball.x<goalRight){if(ball.y>field.y+field.h+field.goalDepth){goal(1);return;}}else{ball.y=bottom;ball.vy=-Math.abs(ball.vy)*.82;}}
}
function update(dt){elapsed+=dt;if(phase==='end')return;if(phase==='goal'){phaseTimer-=dt;if(phaseTimer<=0){phase='play';ui.toast.classList.remove('show');resetPositions();updateHUD();}return;}timeLeft-=dt;if(timeLeft<=0){timeLeft=0;phase='end';ui.end.classList.add('show');document.getElementById('finalHome').textContent=String(score[0]).padStart(2,'0');document.getElementById('finalAway').textContent=String(score[1]).padStart(2,'0');document.getElementById('result').textContent=score[0]>score[1]?'VICTORY':score[0]<score[1]?'DEFEAT':'DRAW';document.getElementById('result').style.color=score[0]>=score[1]?cyan:coral;updateHUD();return;}
powerTimer-=dt;if(powerTimer<=0&&!powerOrb&&!powerEffect){spawnPower();powerTimer=12;}if(powerEffect){powerEffect.time-=dt;if(powerEffect.time<=0){powerEffect=null;players.forEach(p=>{p.boost=0;p.freeze=0;});}}if(powerOrb)powerOrb.phase+=dt*3;
const h=players[0];let ax=input.x,ay=input.y;if(input.keys.ArrowLeft||input.keys.KeyA)ax-=1;if(input.keys.ArrowRight||input.keys.KeyD)ax+=1;if(input.keys.ArrowUp||input.keys.KeyW)ay-=1;if(input.keys.ArrowDown||input.keys.KeyS)ay+=1;if(hypot(ax,ay)>1){const z=hypot(ax,ay);ax/=z;ay/=z;}movePlayer(h,ax,ay,dt);for(let i=1;i<players.length;i++){const p=players[i],dir=aiMove(p,dt);movePlayer(p,dir.x,dir.y,dt);}collidePlayers();updateBall(dt);collideBall();
if(kickQueued){kick(h);kickQueued=false;}if(dashQueued){dash(h);dashQueued=false;}if(powerOrb){for(const p of players){if(p.team===0&&hypot(p.x-powerOrb.x,p.y-powerOrb.y)<p.r+powerOrb.r){activatePower(p);break;}}}if(powerEffect?.type==='speed'&&powerEffect.time>0)h.boost=powerEffect.time;
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.life<=0){particles.splice(i,1);continue;}p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.92,dt*60);p.vy*=Math.pow(.92,dt*60);}shake=Math.max(0,shake-dt*18);updateHUD();}

