function pathRound(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function glowLine(color,width=1,blur=8){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.shadowColor=color;ctx.shadowBlur=blur;ctx.stroke();ctx.shadowBlur=0;}
function drawPitch(){const f=field,cx=W/2,cy=f.y+f.h/2;ctx.fillStyle='#060d18';ctx.fillRect(0,0,W,H);const bg=ctx.createRadialGradient(cx,cy,20,cx,cy,Math.max(W,H)*.8);bg.addColorStop(0,'#102133');bg.addColorStop(.55,'#081321');bg.addColorStop(1,'#040912');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
// subtle stadium grid
ctx.save();ctx.beginPath();ctx.rect(f.x,f.y,f.w,f.h);ctx.clip();ctx.strokeStyle='#92d9ed09';ctx.lineWidth=1;for(let x=f.x;x<f.x+f.w;x+=24){ctx.beginPath();ctx.moveTo(x,f.y);ctx.lineTo(x,f.y+f.h);ctx.stroke();}for(let y=f.y;y<f.y+f.h;y+=24){ctx.beginPath();ctx.moveTo(f.x,y);ctx.lineTo(f.x+f.w,y);ctx.stroke();}
for(let i=0;i<8;i++){ctx.fillStyle=i%2?'#ffffff03':'#4bffff04';ctx.fillRect(f.x,f.y+i*f.h/8,f.w,f.h/8);}
ctx.restore();
// outer neon boundary and markings
pathRound(f.x,f.y,f.w,f.h,8);glowLine('#32f4ff99',1.5,12);ctx.strokeStyle='#a5faff66';ctx.lineWidth=1;ctx.strokeRect(f.x+10,f.y+10,f.w-20,f.h-20);
ctx.strokeStyle='#b9e8f02b';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(f.x,cy);ctx.lineTo(f.x+f.w,cy);ctx.stroke();ctx.beginPath();ctx.arc(cx,cy,f.r,0,Math.PI*2);glowLine('#6ee9f666',1,5);ctx.beginPath();ctx.arc(cx,cy,2.4,0,Math.PI*2);ctx.fillStyle='#d5feff';ctx.fill();
const boxW=f.w*.62,boxH=f.h*.115;ctx.strokeStyle='#8feefa4d';ctx.lineWidth=1;ctx.strokeRect(cx-boxW/2,f.y,boxW,boxH);ctx.strokeRect(cx-boxW/2,f.y+f.h-boxH,boxW,boxH);ctx.strokeRect(cx-f.w*.36,f.y-3, f.w*.72,6);ctx.strokeRect(cx-f.w*.36,f.y+f.h-3,f.w*.72,6);
// goal frames and mouth glow
for(const [gy,team] of [[f.y,coral],[f.y+f.h,cyan]]){const gx=cx-f.goalW/2;ctx.save();ctx.shadowColor=team;ctx.shadowBlur=18;ctx.strokeStyle=team+'cc';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(gx,gy);ctx.lineTo(gx,gy+(gy===f.y?-f.goalDepth:f.goalDepth));ctx.lineTo(gx+f.goalW,gy+(gy===f.y?-f.goalDepth:f.goalDepth));ctx.lineTo(gx+f.goalW,gy);ctx.stroke();ctx.restore();ctx.strokeStyle='#ffffff12';ctx.lineWidth=1;for(let i=1;i<6;i++){const xx=gx+i*f.goalW/6;ctx.beginPath();ctx.moveTo(xx,gy);ctx.lineTo(xx,gy+(gy===f.y?-f.goalDepth:f.goalDepth));ctx.stroke();}}
// glowing edge accents
const edge=ctx.createLinearGradient(0,f.y,0,f.y+f.h);edge.addColorStop(0,coral+'26');edge.addColorStop(.48,'#ffffff00');edge.addColorStop(1,cyan+'26');ctx.strokeStyle=edge;ctx.lineWidth=4;ctx.strokeRect(f.x+2,f.y+2,f.w-4,f.h-4);
}
