function render(){ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawPitch();drawPower();drawParticles();drawBall();drawPlayers();ctx.restore();}
const joy=document.getElementById('joystick'),knob=document.getElementById('knob'),kickBtn=document.getElementById('kick'),dashBtn=document.getElementById('dash');
function joyStart(e){e.preventDefault();input.joyId=e.pointerId;const rect=joy.getBoundingClientRect();input.joyOrigin={x:rect.left+rect.width/2,y:rect.top+rect.height/2};joy.setPointerCapture(e.pointerId);joyMove(e);}
function joyMove(e){if(input.joyId!==e.pointerId||!input.joyOrigin)return;const dx=e.clientX-input.joyOrigin.x,dy=e.clientY-input.joyOrigin.y,max=33,l=hypot(dx,dy),scale=l>max?max/l:1;knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;input.x=clamp(dx/max,-1,1);input.y=clamp(dy/max,-1,1);}
function joyEnd(e){if(input.joyId!==e.pointerId)return;input.joyId=null;input.joyOrigin=null;input.x=0;input.y=0;knob.style.transform='translate(0,0)';}
joy.addEventListener('pointerdown',joyStart);window.addEventListener('pointermove',joyMove);window.addEventListener('pointerup',joyEnd);window.addEventListener('pointercancel',joyEnd);
// Allow a thumb to begin movement anywhere in the left half, then bring the joystick to it.
canvas.addEventListener('pointerdown',e=>{if(e.clientX<W*.56&&e.clientY>H*.38&&!input.joyId){joy.style.left=`${clamp(e.clientX-48,8,W*.42)}px`;joy.style.bottom='auto';joy.style.top=`${clamp(e.clientY-48,H*.45,H-112)}px`;const r=joy.getBoundingClientRect();input.joyId=e.pointerId;input.joyOrigin={x:r.left+r.width/2,y:r.top+r.height/2};canvas.setPointerCapture(e.pointerId);joyMove(e);}});
function buttonPress(btn,fn){btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.classList.add('pressed');fn();});for(const name of ['pointerup','pointercancel','pointerleave'])btn.addEventListener(name,()=>btn.classList.remove('pressed'));}
buttonPress(kickBtn,()=>{kickQueued=true;});buttonPress(dashBtn,()=>{dashQueued=true;});
window.addEventListener('keydown',e=>{input.keys[e.code]=true;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','ShiftLeft','ShiftRight'].includes(e.code))e.preventDefault();if(e.code==='Space')kickQueued=true;if(e.code==='ShiftLeft'||e.code==='ShiftRight')dashQueued=true;});window.addEventListener('keyup',e=>{input.keys[e.code]=false;});
document.getElementById('restart').addEventListener('click',restart);
function frame(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);render();ui.cooldown.style.setProperty('--cool',`${players[0]?players[0].dashCd/2.2*100:0}%`);requestAnimationFrame(frame);}
updateHUD();requestAnimationFrame(frame);
})();
</script>
</body>
</html>

